function e(string $value): string { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }
function nav(string $href, string $label, string $current): string { $active = $href === $current ? ' active' : ''; return '<a class="'.$active.'" href="'.e($href).'">'.e($label).'</a>'; }
function layout(string $title, string $current, string $content): void {
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' | Laravel POS</title><style>'.css().'</style></head><body><nav><div class="nav"><a class="brand" href="/">P <span>Laravel POS</span></a><div class="links">'.nav('/','Home',$current).nav('/about','About',$current).nav('/customers','Customers',$current).nav('/users','Users',$current).'</div></div></nav><main>'.$content.'</main><footer>IT0049 Web System Technologies · Laravel Foundations</footer></body></html>';
}
function css(): string { return ':root{--navy:#10233f;--blue:#2563eb;--ink:#172033;--muted:#64748b;--line:#e2e8f0;--green:#15803d;--green-bg:#dcfce7;--red:#b91c1c;--red-bg:#fee2e2}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;color:var(--ink);background:#f8fafc}a{color:inherit;text-decoration:none}nav{background:var(--navy);color:#fff}.nav{max-width:1120px;margin:auto;padding:18px 24px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:10px;font-weight:800}.brand:first-letter{display:inline-block}.brand span{color:#fff}.links{display:flex;gap:6px}.links a{padding:9px 13px;border-radius:8px;color:#cbd5e1;font-size:14px}.links a.active,.links a:hover{background:#1e3a5f;color:#fff}main{max-width:1120px;margin:auto;padding:48px 24px 70px}.eyebrow{color:var(--blue);font-weight:800;text-transform:uppercase;letter-spacing:.12em;font-size:12px}h1{font-size:clamp(32px,5vw,54px);line-height:1.04;letter-spacing:-.055em;margin:12px 0 18px;color:var(--navy)}h2{margin:0 0 10px;color:var(--navy)}p{color:var(--muted);line-height:1.7}.hero{display:grid;grid-template-columns:1.2fr .8fr;align-items:center;gap:56px}.hero p{font-size:18px}.button{display:inline-block;margin-top:14px;padding:12px 17px;border-radius:9px;background:var(--blue);color:#fff;font-weight:700}.secondary{background:#e2e8f0;color:var(--navy);margin-left:8px}.hero-card{background:linear-gradient(145deg,#10233f,#1d4ed8);border-radius:22px;padding:28px;color:#fff}.big{font-size:52px;font-weight:900;margin:18px 0 8px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:45px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px}.page-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:28px}.page-head h1{font-size:42px;margin-bottom:10px}.page-head p{margin:0}.table-wrap{overflow:auto;background:#fff;border:1px solid var(--line);border-radius:14px}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:16px 18px;border-bottom:1px solid var(--line);font-size:14px}th{background:#f8fafc;color:#475569;font-size:12px;text-transform:uppercase;letter-spacing:.08em}tr:last-child td{border:0}.badge{display:inline-block;border-radius:999px;padding:5px 10px;font-size:12px;font-weight:700}.active{color:var(--green);background:var(--green-bg)}.inactive{color:var(--red);background:var(--red-bg)}footer{text-align:center;padding:24px;color:#94a3b8;font-size:13px;border-top:1px solid var(--line);background:#fff}@media(max-width:760px){.nav,.page-head{align-items:flex-start;flex-direction:column}.hero{grid-template-columns:1fr;gap:30px}.grid{grid-template-columns:1fr}}'; }

if ($path === '/') {
    layout('Home', '/', '<section class="hero"><div><div class="eyebrow">IT0049 · Laravel Foundations</div><h1>Simple pages.<br>Clear MVC flow.</h1><p>This starter point-of-sale application demonstrates how Laravel routes connect to controllers, and how controllers pass data to Blade views.</p><a class="button" href="/customers">View customer accounts</a><a class="button secondary" href="/about">Learn about the app</a></div><div class="hero-card"><div class="eyebrow" style="color:#bfdbfe">Application overview</div><div class="big">4</div><div>connected Laravel pages</div><p style="color:#dbeafe">Routes → controllers → Blade views</p></div></section><section class="grid"><div class="card"><div class="eyebrow">01</div><h2>About</h2><p>Course information passed from a controller to a Blade view.</p></div><div class="card"><div class="eyebrow">02</div><h2>Customers</h2><p>Five sample records rendered with a foreach loop.</p></div><div class="card"><div class="eyebrow">03</div><h2>Users</h2><p>Sample system accounts and their roles.</p></div></section>');
