} elseif ($path === '/customers' || $path === '/users') {
    $isCustomers = $path === '/customers'; $rows = $isCustomers ? $customers : $users; $heading = $isCustomers ? 'Customer Accounts' : 'User Accounts'; $controller = $isCustomers ? 'CustomerController' : 'UserController'; $headers = $isCustomers ? ['#','Customer','Email','Phone','Status'] : ['#','User','Email','Role','Status']; $html = '<section><div class="page-head"><div><div class="eyebrow">Temporary static data</div><h1>'.e($heading).'</h1><p>Five sample records prepared by <code>'.e($controller).'</code>.</p></div><a class="button" href="'.($isCustomers?'/users':'/customers').'">View '.($isCustomers?'user':'customer').' accounts</a></div><div class="table-wrap"><table><thead><tr>'; foreach($headers as $header) $html .= '<th>'.e($header).'</th>'; $html .= '</tr></thead><tbody>'; foreach($rows as $row) { $html .= '<tr><td>'.e((string)$row['id']).'</td><td><strong>'.e($row['name']).'</strong></td><td>'.e($row['email']).'</td><td>'.e($isCustomers?$row['phone']:$row['role']).'</td><td><span class="badge '.strtolower(e($row['status'])).'">'.e($row['status']).'</span></td></tr>'; } $html .= '</tbody></table></div></section>'; layout($heading, $path, $html);
} else { http_response_code(404); layout('Page not found', '', '<h1>Page not found</h1><p>The requested page does not exist.</p><a class="button" href="/">Return home</a>'); }
